-- Esquema vigente de packing_tracker. Incluye hasta la migración 0002.
-- Ejecutar una sola vez sobre una base vacía, como usuario packing:
--   psql -U packing -d packing_tracker -f db/init.sql
-- Este script deja la base en la versión más avanzada.
-- UNIDADES_TRANSPORTE queda vacía. UNIDADES_ESTATUS y UNIDADES_TIPOS nacen con su catálogo.
-- No corras las migraciones después. Las unidades de prueba están en db/seed.sql.

CREATE TABLE "UNIDADES_ESTATUS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true
);

CREATE TABLE "UNIDADES_TIPOS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true
);

CREATE TABLE "UNIDADES_TRANSPORTE" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "ID_TIPO" integer NOT NULL,
  "PLACAS" text NOT NULL UNIQUE,
  "NUMERO_ECONOMICO" text UNIQUE,
  "MARCA" text,
  "MODELO" text,
  "ANIO" integer,
  "NUMERO_SERIE" text UNIQUE,
  "CAPACIDAD_CARGA_KG" numeric(12, 2),
  "CAPACIDAD_VOLUMEN_M3" numeric(12, 2),
  "ID_ESTATUS" integer NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "UNIDADES_TRANSPORTE_ID_TIPO_FK"
    FOREIGN KEY ("ID_TIPO") REFERENCES "UNIDADES_TIPOS" ("ID"),
  CONSTRAINT "UNIDADES_TRANSPORTE_ID_ESTATUS_FK"
    FOREIGN KEY ("ID_ESTATUS") REFERENCES "UNIDADES_ESTATUS" ("ID"),
  CONSTRAINT "UNIDADES_TRANSPORTE_ANIO_CHK" CHECK (
    "ANIO" IS NULL OR "ANIO" BETWEEN 1980 AND 2100
  ),
  CONSTRAINT "UNIDADES_TRANSPORTE_CAPACIDAD_KG_CHK" CHECK (
    "CAPACIDAD_CARGA_KG" IS NULL OR "CAPACIDAD_CARGA_KG" >= 0
  ),
  CONSTRAINT "UNIDADES_TRANSPORTE_CAPACIDAD_M3_CHK" CHECK (
    "CAPACIDAD_VOLUMEN_M3" IS NULL OR "CAPACIDAD_VOLUMEN_M3" >= 0
  )
);

CREATE INDEX "UNIDADES_TRANSPORTE_ID_TIPO_IDX" ON "UNIDADES_TRANSPORTE" ("ID_TIPO");

CREATE INDEX "UNIDADES_TRANSPORTE_ID_ESTATUS_IDX" ON "UNIDADES_TRANSPORTE" ("ID_ESTATUS");

